import * as THREE from './three.module.js';
import {createWindMascotFactory,MASCOT_KINDS} from './wind-mascot.js?v=friends-r53';
const canvas=document.querySelector('#mascot'),stage=document.querySelector('#stage');
try{
 const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(32,1,.1,40);
 scene.add(new THREE.HemisphereLight('#f2fcff','#c4b9a0',2.4));const sun=new THREE.DirectionalLight('#fff4dd',3);sun.position.set(-3,6,5);scene.add(sun);const fill=new THREE.DirectionalLight('#a6e2fa',1.4);fill.position.set(4,3,-3);scene.add(fill);
 const texture=await new THREE.TextureLoader().loadAsync('./assets/sumgyeol_symbol_blue.png');texture.colorSpace=THREE.SRGBColorSpace;
 const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(64,64,0,64,64,64);gradient.addColorStop(0,'rgba(72,103,106,.24)');gradient.addColorStop(.45,'rgba(72,103,106,.12)');gradient.addColorStop(1,'rgba(72,103,106,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);
 const shadowGeometry=new THREE.PlaneGeometry(1.75,1.35),shadowMaterial=new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false});
 const friends=MASCOT_KINDS.map((spec,i)=>{const a=createWindMascotFactory({kind:spec.id,symbolTexture:texture}).create(scene,{phase:i*.6});a.shadow.visible=false;const shadow=new THREE.Mesh(shadowGeometry,shadowMaterial);shadow.rotation.x=-Math.PI/2;shadow.position.y=.002;scene.add(shadow);return {a,shadow,spec};});
 let action='idle',selection='all',time=0,last=performance.now(),drag=null;
 function resize(){const {width,height}=stage.getBoundingClientRect();renderer.setSize(width,height,false);camera.aspect=width/height;if(selection==='all')camera.position.set(0,2,Math.max(8.6,10.8/camera.aspect));else camera.position.set(1.8,1.55,4.5).multiplyScalar(width<height*.8?1.12:1);camera.lookAt(0,.85,0);camera.updateProjectionMatrix();}
 function select(kind){selection=MASCOT_KINDS.some(s=>s.id===kind)?kind:'all';const spec=MASCOT_KINDS.find(s=>s.id===selection);document.querySelector('#friendName').textContent=spec?.name??'숨결 친구들';document.querySelector('#friendDescription').textContent=spec?.description??'바람, 귤, 돌, 구름, 새싹. 다섯 친구가 함께 걷는 캠퍼스예요. 마음에 드는 친구를 골라보세요.';document.querySelector('.enter').href='./index.html?revision=friends-r53&character='+(spec?.id??'wind')+'&view=booth';document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===selection)));friends.forEach(({a,shadow,spec},i)=>{a.player.visible=shadow.visible=selection==='all'||selection===spec.id;a.player.position.set(selection==='all'?(i-2)*1.25:0,0,0);a.body.rotation.y=selection==='all'?.05:-.1;shadow.position.x=a.player.position.x;});if(spec)try{localStorage.setItem('sumgyeol-character',spec.id);}catch{}resize();}
 document.querySelectorAll('[data-kind]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.kind)));
 document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{action=button.dataset.action;time=0;document.querySelectorAll('[data-action]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
 function turn(delta){friends.filter(f=>f.a.player.visible).forEach(f=>{f.a.body.rotation.y+=delta;});}
 canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();turn(e.key==='ArrowLeft'?-.3:.3);}});
 canvas.addEventListener('pointerdown',e=>{drag={id:e.pointerId,x:e.clientX};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag?.id!==e.pointerId)return;turn((e.clientX-drag.x)*.012);drag.x=e.clientX;});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>{drag=null;});
 new ResizeObserver(resize).observe(stage);select(new URLSearchParams(location.search).get('character')??'all');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(!document.hidden){time+=dt;const jump=action==='jump'&&time<.85,phase=Math.min(time/.85,1);for(const {a}of friends){if(!a.player.visible)continue;a.player.position.y=jump?Math.sin(phase*Math.PI)*.6:0;a.setGreeting(action==='wave');a.setTalking(action==='talk');a.update(dt,{speed:action==='run'?16:action==='walk'?3:0,grounded:!jump,reducedMotion:reduced.matches});}shadowMaterial.opacity=jump?.7:1;renderer.render(scene,camera);canvas.dataset.state=JSON.stringify({selection,visible:friends.filter(f=>f.a.player.visible).map(f=>f.a.metadata),drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles});}requestAnimationFrame(frame);}
 requestAnimationFrame(frame);
}catch(error){console.error(error);document.querySelector('#error').hidden=false;}
